'use strict';
function performanceScope(){
 const rows=regionalData(),campuses=rows.flatMap(r=>r.campuses),metrics=campuses.map(campusMetrics);
 const sum=key=>metrics.reduce((v,m)=>v+m[key],0),power=sum('power'),it=sum('it');
 return {rows,campuses,metrics,power,it,pue:power/it,installed:sum('installed'),cooling:sum('cooling'),coolingCapacity:sum('coolingCapacity'),backup:sum('backup'),backupCapacity:sum('backupCapacity'),racks:sum('occupied'),rackCapacity:sum('capacity'),renewable:campuses.reduce((v,s,i)=>v+s.power*metrics[i].renewable,0)/power,costs:[0,1,2].map(i=>rows.reduce((v,r)=>v+r.costs[i],0)),alerts:baseAlerts.filter(a=>campuses.some(s=>s.id===a.site))};
}
function performanceLineChart(series,unit,description){
 const maximum=Math.max(...series.flatMap(s=>s.values))*1.15,top=20,bottom=162,left=48,right=530;
 return `<div class="performance-line-chart"><svg viewBox="0 0 550 195" role="img" aria-label="${esc(description)}">${Array.from({length:5},(_,i)=>{const y=bottom-i*(bottom-top)/4;return `<path d="M${left} ${y}H${right}" stroke="#385263" stroke-width=".7"/><text x="3" y="${y+3}" fill="#8eaabc" font-size="9">${(maximum*i/4).toFixed(maximum<10?1:0)} ${unit}</text>`}).join('')}${series.map(s=>{const pts=s.values.map((v,i)=>`${left+i*(right-left)/(s.values.length-1)},${bottom-v/maximum*(bottom-top)}`).join(' ');return `<polyline points="${pts}" fill="none" stroke="${s.color}" stroke-width="2"/>`}).join('')}${[0,4,8,12,16,20,24].map(h=>`<text x="${left+h*(right-left)/24}" y="184" text-anchor="middle" fill="#91adbf" font-size="9">${String(h%24).padStart(2,'0')}:00</text>`).join('')}</svg><div class="performance-legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${s.label}<b>${s.values.at(-1).toFixed(2)} ${unit}</b></span>`).join('')}</div></div>`;
}
function performanceDay(value,phase=0){return Array.from({length:25},(_,i)=>value*(1+.085*(Math.sin(i*.31+phase+regionalMonth*.1)-Math.sin(24*.31+phase+regionalMonth*.1))))}
function performanceBuildings(scope){
 return scope.campuses.flatMap(s=>{
  const weights=Array.from({length:s.buildings},(_,i)=>1-i*.08),total=weights.reduce((a,b)=>a+b,0),occupied=Math.round(s.buildings*80*s.racks/100);
  return weights.map((w,i)=>({site:s,id:`DC-${String(i+1).padStart(2,'0')}`,power:s.power*w/total,pue:s.pue,racks:Math.floor(occupied/s.buildings)+(i<occupied%s.buildings?1:0),capacity:80,temp:23.1+i*.4+sites.indexOf(s)*.1,status:i===0?s.status:'operational',alarms:i===0?s.alarms:0}));
 });
}
function performanceCostBars(scope){
 const currentSeason=1+Math.sin((regionalMonth-3)*Math.PI/6)*.09,currentDays=new Date(2026,regionalMonth+1,0).getDate();
 const values=regionalMonths.map((_,i)=>scope.costs.reduce((a,b)=>a+b,0)/currentSeason/currentDays*(1+Math.sin((i-3)*Math.PI/6)*.09)*new Date(2026,i+1,0).getDate()),maximum=Math.max(...values)*1.15;
 return `<svg class="performance-cost-chart" viewBox="0 0 510 178" role="img" aria-label="Illustrative monthly total utility cost in millions of EGP">${[0,1,2,3].map(i=>`<path d="M42 ${145-i*39}H500" stroke="#385263" stroke-width=".7"/><text x="0" y="${148-i*39}" fill="#91adbf" font-size="8">${(maximum*i/3/1e6).toFixed(1)}M</text>`).join('')}${values.map((v,i)=>`<rect x="${52+i*37}" y="${145-v/maximum*117}" width="23" height="${v/maximum*117}" rx="2" fill="${i===regionalMonth?'#66e1c2':'#6e9ce7'}" opacity="${i===regionalMonth?1:.65}"/><text x="${63+i*37}" y="164" text-anchor="middle" fill="#a7bece" font-size="9">${regionalMonths[i]}</text>`).join('')}</svg>`;
}
const performanceOriginalRegional=regionalPerformance;
regionalPerformance=function(){
 const q=performanceScope(),buildings=performanceBuildings(q),totalCost=q.costs.reduce((a,b)=>a+b,0),critical=q.alerts.filter(a=>a.severity==='critical').length;
 const kpis=`<div class="performance-kpis">${kpi('Facility power',q.power.toFixed(2),'MW','IT '+q.it.toFixed(2)+' MW','current demand',0,C.blue)}${kpi('Power usage effectiveness',q.pue.toFixed(2),'PUE','Target 1.30','facility / IT load',1)}${kpi('Rack occupancy',(100*q.racks/q.rackCapacity).toFixed(1),'%',q.racks+' / '+q.rackCapacity,'rack positions',3,C.purple)}${kpi('Cooling demand',q.cooling.toFixed(2),'MW',(100*q.cooling/q.coolingCapacity).toFixed(0)+'%','installed cooling load',2)}${kpi('Renewable contribution',q.renewable.toFixed(1),'%','Solar · hydro · wind','illustrative source mix',0)}${kpi('Active source alarms',q.alerts.length,'events',critical+' critical','in selected scope',1,critical?C.red:C.mint)}</div>`;
 const gauges=`<section class="performance-gauges" aria-label="Selected scope capacity gauges">${campusGauge('Total power utilization',+q.power.toFixed(2),+q.installed.toFixed(2),'MW',C.blue)}${campusGauge('Energy utilization',+(100*q.power/q.installed).toFixed(1),100,'%',C.mint)}${campusGauge('Load running on backup',+q.backup.toFixed(2),+q.backupCapacity.toFixed(2),'MW',C.amber)}${campusGauge('Total rack utilization',q.racks,q.rackCapacity,'racks',C.purple)}${campusGauge('Cooling system power',+q.cooling.toFixed(2),+q.coolingCapacity.toFixed(2),'MW',C.mint)}</section>`;
 const power=panel('Facility and IT power','Last 24 hours · illustrative demand profile',performanceLineChart([{label:'Facility',values:performanceDay(q.power),color:C.blue},{label:'IT load',values:performanceDay(q.it),color:C.mint}],'MW','Facility and IT power over 24 hours'),'<span class="chip">24 HOURS</span>');
 const sources=panel('Energy source distribution','Power-weighted renewable share across the selected scope',`<div class="performance-source-donut">${donut(+q.renewable.toFixed(1),'Renewable',C.mint)}<div>${['Solar','Hydro','Wind','Grid / other'].map((n,i)=>{const value=i===0?q.renewable*.5:i===1?q.renewable*.25:i===2?q.renewable*.25:100-q.renewable;return `<div class="performance-source-row"><span><i style="background:${[C.blue,C.mint,C.purple,C.amber][i]}"></i>${n}</span><strong>${value.toFixed(1)}%</strong><small>${(q.power*value/100).toFixed(2)} MW</small></div>`}).join('')}</div></div>`);
 const cooling=panel('Cooling and thermal performance','Cooling load, supply air, and return-air conditions',performanceLineChart([{label:'Cooling',values:performanceDay(q.cooling,1),color:C.mint}],'MW','Cooling demand over 24 hours')+`<div class="performance-inline-metrics"><span>Supply air<b>18.2 °C</b></span><span>Return air<b class="${q.alerts.some(a=>a.system==='mechanical')?'negative':''}">${q.alerts.some(a=>a.system==='mechanical')?'29.4':'25.8'} °C</b></span><span>COP<b>5.30</b></span><span>Humidity<b>46 %RH</b></span></div>`);
 const utility=panel('Utility cost trend',`${regionalMonths[regionalMonth]} 2026 · estimated monthly total`,performanceCostBars(q)+`<div class="performance-utility-totals">${q.costs.map((v,i)=>`<span>${['Water','Electricity','Natural gas'][i]}<b>EGP ${regionalCost(v)}</b><small>${(v/totalCost*100).toFixed(1)}% of estimated cost</small></span>`).join('')}</div>`,'<span class="chip">EGP '+regionalCost(totalCost)+'</span>');
 const comparison=panel('Building capacity and performance',`${buildings.length} buildings · readings follow the selected location`,`<div class="performance-buildings"><div class="performance-building-header"><span>Building</span><span>PUE</span><span>Power</span><span>Rack occupancy</span><span>Inlet / status</span></div>${buildings.map(b=>`<div class="performance-building-row"><span><strong>${b.site.short} / ${b.id}</strong><small>${esc(b.site.name)}</small></span><b>${b.pue.toFixed(2)}</b><b>${b.power.toFixed(2)} MW</b><span><span class="performance-building-meter"><i style="width:${b.racks/b.capacity*100}%"></i></span><small>${b.racks} / ${b.capacity} racks</small></span><span><strong>${b.temp.toFixed(1)} °C</strong>${status(b.status)}</span></div>`).join('')}</div>`);
 const alerts=panel('Alarms and operational priorities','Source-specific events in the selected campus or region',q.alerts.length?`<div class="performance-alarm-list">${q.alerts.map(a=>`<button class="performance-alarm" data-alert="${a.id}"><span class="chip ${a.severity==='critical'?'red':'amber'}">${a.severity}</span><span><strong>${esc(a.title)}</strong><small>${esc(a.asset)} · ${a.reading}</small></span><b>Inspect ↗</b></button>`).join('')}</div>`:`<div class="performance-no-alarms"><span class="chip green">No active source alarms</span><strong>Systems operating within configured limits</strong><p>Continue routine monitoring and scheduled inspections for the selected scope.</p></div>`);
 const headroom=panel('Available operational headroom','Remaining capacity for the selected campus or region',`<div class="performance-headroom">${[['Power headroom',(q.installed-q.power).toFixed(2)+' MW',q.power/q.installed,C.blue],['Cooling headroom',(q.coolingCapacity-q.cooling).toFixed(2)+' MW',q.cooling/q.coolingCapacity,C.mint],['Free rack positions',(q.rackCapacity-q.racks)+' racks',q.racks/q.rackCapacity,C.purple]].map(([label,value,used,color])=>`<div><span>${label}<b>${value}</b></span><div class="bar-track"><i style="display:block;height:100%;width:${(1-used)*100}%;background:${color}"></i></div><small>${((1-used)*100).toFixed(1)}% available</small></div>`).join('')}</div>`);
 // Retain the reference comparison row, then fill the campus page with operational detail.
 return `<div class="performance-rich">${kpis}${performanceOriginalRegional()}${gauges}<div class="performance-visual-grid">${power}${sources}${cooling}${utility}</div><div class="performance-operational-grid">${comparison}<div class="performance-operational-side">${headroom}${alerts}</div></div></div>`;
};
